async function describe(node, depth){
  const obj = {name:node.name, type:node.type};
  if(depth<6){
    if(node.type==='TEXT'){
      obj.characters = node.characters;
      try{ obj.fontName = node.fontName; }catch(e){}
      obj.fontSize = node.fontSize;
      try{ obj.fills = node.fills.map(f=>({type:f.type,color:f.color,opacity:f.opacity})); }catch(e){}
    } else if(node.type==='RECTANGLE'||node.type==='ELLIPSE'){
      try{ obj.fills = node.fills.map(f=>({type:f.type,color:f.color,opacity:f.opacity,imageHash:f.imageHash})); }catch(e){}
      obj.cornerRadius = node.cornerRadius;
      if(node.fills && node.fills[0] && node.fills[0].type==='SOLID'){ obj.fillColor=node.fills[0].color; }
    } else if(node.type==='FRAME'||node.type==='COMPONENT'||node.type==='INSTANCE'){
      obj.width=node.width; obj.height=node.height;
      try{ obj.fills = node.fills.map(f=>({type:f.type,color:f.color,opacity:f.opacity})); obj.cornerRadius=node.cornerRadius; }catch(e){}
      obj.children = node.children.map(c=>describe(c, depth+1));
    } else {
      obj.width=node.width; obj.height=node.height;
      obj.children = node.children ? node.children.map(c=>describe(c, depth+1)) : [];
    }
  } else {
    obj.width=node.width; obj.height=node.height; obj.name=node.name+'(...)';
  }
  return obj;
}
