async function describe(node, depth, max){
  const obj = {name:node.name, type:node.type};
  obj.width=node.width; obj.height=node.height;
  if(node.x!==undefined && depth>0){ obj.x=Math.round(node.x); obj.y=Math.round(node.y); }
  if(node.type==='TEXT'){ obj.characters=node.characters; try{obj.fontName=node.fontName;}catch(e){} obj.fontSize=node.fontSize; try{obj.fills=node.fills.map(f=>f.type==='SOLID'?f.color:f.type);}catch(e){} obj.textAlignHorizontal=node.textAlignHorizontal; }
  if(node.type==='RECTANGLE'){ try{obj.fills=node.fills.map(f=>({type:f.type,color:f.color,opacity:f.opacity}));}catch(e){} obj.cornerRadius=node.cornerRadius; }
  if(depth<max && node.children){ obj.children=node.children.map(c=>describe(c,depth+1,max)); }
  return obj;
}
