function line(n,d){let s='';for(let i=0;i<d;i++)s+='  ';s+=n.type+' "'+n.name+'" ('+Math.round(n.x)+','+Math.round(n.y)+' '+Math.round(n.width)+'x'+Math.round(n.height)+')';
if(n.type==='TEXT'){s+=' >>>"'+n.characters+'" fs='+n.fontSize;}return s;}
async function walk(n,d,lines,stop){lines.push(line(n,d));if(d<stop&&n.children){for(const c of n.children)await walk(c,d+1,lines,stop);}}
