  const n=await figma.getNodeByIdAsync(id);
  const lines=[];
  function walk(c,dep){
    let s='';
    for(let i=0;i<dep;i++)s+='  ';
    s+=c.type+':'+c.name;
    if(c.type==='TEXT') s+=' = "'+c.characters+'"';
    if(c.type==='RECTANGLE'||c.type==='ELLIPSE'||c.type==='FRAME'){ try{ const fl=c.fills.map(f=>f.type); if(fl.includes('IMAGE')) s+=' [IMG '+Math.round(c.width)+'x'+Math.round(c.height)+']'; else s+=' ['+fl.join(',')+']'; }catch(e){} }
    if(c.type==='INSTANCE'){ try{ s+=' {main:'+c.mainComponent.name+'}'; }catch(e){} }
    s+=' ('+Math.round(c.width)+'x'+Math.round(c.height)+', '+Math.round(c.x)+','+Math.round(c.y)+')';
    lines.push(s);
    if(c.children) c.children.forEach(k=>walk(k,dep+1));
  }
  walk(n,0);
  return lines;
}
