function rec(n, d, out, max){
  if(d>max) return;
  let note=n.type+':'+n.name+'@('+Math.round(n.x)+','+Math.round(n.y)+') '+Math.round(n.width)+'x'+Math.round(n.height);
  if(n.type==='TEXT') note+=' "'+n.characters+'"';
  if(n.type==='INSTANCE'){ try{note+=' [main='+n.mainComponent.name+']';}catch(e){note+=' [inst]';} }
  // image fill detection
  try{ if(n.type==='RECTANGLE'&&n.fills&&n.fills[0]&&n.fills[0].type==='IMAGE') note+=' IMG'; if(n.type==='FRAME'&&n.fills&&n.fills[0]&&n.fills[0].type==='IMAGE') note+=' IMG'; }catch(e){}
  out.push('  '.repeat(d)+note);
  if(n.children) n.children.forEach(c=>rec(c,d+1,out,max));
}
const out=[]; rec(home,0,out,3);
return out.join('\n');

